-- Additive Workspace implementation. New capabilities have no role grants.
begin;
insert into public.permissions(id,description) select m||'.'||a,'Workspace '||m||' '||a from unnest(array['priorities','platform','events']) m cross join unnest(array['read','write','delete']) a;
alter table public.activities add column workspace_kind text check(workspace_kind is null or workspace_kind='priorities'), add column team_department text references public.departments(id) on delete restrict, add column priority text not null default 'Medium' check(priority in ('Low','Medium','High','Urgent'));
alter table public.activities add constraint team_priority_fields check(workspace_kind is distinct from 'priorities' or (department is null and team_department is not null and assigned_to is not null and owner_id is not null and due_at is not null and status in ('To Do','In Progress','Completed','On Hold') and length(trim(title)) between 1 and 200));
grant insert(workspace_kind,team_department,priority),update(team_department,priority) on public.activities to authenticated;
create index activities_priority_assignee_idx on public.activities(workspace_kind,assigned_to,due_at);
create table public.it_projects(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 200),platform text not null check(length(trim(platform)) between 1 and 200),description text not null default '' check(length(description)<=5000),responsible_id uuid not null references public.employee_profiles(id) on delete restrict,start_date date not null,deadline date not null check(deadline>=start_date),status text not null check(status in ('Planned','In Progress','On Hold','Completed','Cancelled')),owner_id uuid not null references public.employee_profiles(id) on delete restrict,revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.it_projects enable row level security;
revoke all on public.it_projects from anon,authenticated;
grant select,delete on public.it_projects to authenticated;
grant insert(name,platform,description,responsible_id,start_date,deadline,status,owner_id),update(name,platform,description,responsible_id,start_date,deadline,status) on public.it_projects to authenticated;
create policy module_read on public.it_projects for select to authenticated using(public.has_permission('platform.read'));
create policy module_insert on public.it_projects for insert to authenticated with check(public.has_permission('platform.write') and owner_id=(select auth.uid()));
create policy module_update on public.it_projects for update to authenticated using(public.has_permission('platform.write')) with check(public.has_permission('platform.write'));
create policy module_delete on public.it_projects for delete to authenticated using(public.has_permission('platform.delete'));
create trigger module_revision before update on public.it_projects for each row execute function public.sales_touch_revision();
create trigger module_audit after insert or update or delete on public.it_projects for each row execute function public.audit_business_change();
create trigger module_references before insert or update on public.it_projects for each row execute function public.department_reference_guard();
create table public.it_issues(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.it_projects(id) on delete restrict,title text not null check(length(trim(title)) between 1 and 200),platform text not null check(length(trim(platform)) between 1 and 200),issue_type text not null check(issue_type in ('Task','Issue','Bug','Improvement')),assigned_to uuid not null references public.employee_profiles(id) on delete restrict,priority text not null check(priority in ('Low','Medium','High','Urgent')),status text not null check(status in ('To Do','In Progress','Completed','On Hold')),owner_id uuid not null references public.employee_profiles(id) on delete restrict,revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.it_issues enable row level security;
revoke all on public.it_issues from anon,authenticated;
grant select,delete on public.it_issues to authenticated;
grant insert(project_id,title,platform,issue_type,assigned_to,priority,status,owner_id),update(project_id,title,platform,issue_type,assigned_to,priority,status) on public.it_issues to authenticated;
create policy module_read on public.it_issues for select to authenticated using(public.has_permission('platform.read'));
create policy module_insert on public.it_issues for insert to authenticated with check(public.has_permission('platform.write') and owner_id=(select auth.uid()));
create policy module_update on public.it_issues for update to authenticated using(public.has_permission('platform.write')) with check(public.has_permission('platform.write'));
create policy module_delete on public.it_issues for delete to authenticated using(public.has_permission('platform.delete'));
create trigger module_revision before update on public.it_issues for each row execute function public.sales_touch_revision();
create trigger module_audit after insert or update or delete on public.it_issues for each row execute function public.audit_business_change();
create trigger module_references before insert or update on public.it_issues for each row execute function public.department_reference_guard();
create table public.conference_contacts(id uuid primary key default gen_random_uuid(),account_id uuid not null references public.accounts(id) on delete restrict,contact_type text not null check(length(trim(contact_type)) between 1 and 100),contact_id uuid references public.contacts(id) on delete set null,contact_person text not null default '' check(length(contact_person)<=200),email_phone text not null default '' check(length(email_phone)<=300),country text not null default '' check(length(country)<=100),status text not null check(status in ('Not Contacted','Contacted','Follow-up','Confirmed','Closed')),date_contacted date,topic text not null default '' check(length(topic)<=5000),next_step text not null default '' check(length(next_step)<=500),follow_up_date date,responsible_id uuid not null references public.employee_profiles(id) on delete restrict,check(contact_id is not null or length(trim(contact_person))>0),check(follow_up_date is null or date_contacted is null or follow_up_date>=date_contacted),owner_id uuid not null references public.employee_profiles(id) on delete restrict,revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.conference_contacts enable row level security;
revoke all on public.conference_contacts from anon,authenticated;
grant select,delete on public.conference_contacts to authenticated;
grant insert(account_id,contact_type,contact_id,contact_person,email_phone,country,status,date_contacted,topic,next_step,follow_up_date,responsible_id,owner_id),update(account_id,contact_type,contact_id,contact_person,email_phone,country,status,date_contacted,topic,next_step,follow_up_date,responsible_id) on public.conference_contacts to authenticated;
create policy module_read on public.conference_contacts for select to authenticated using(public.has_permission('events.read'));
create policy module_insert on public.conference_contacts for insert to authenticated with check(public.has_permission('events.write') and owner_id=(select auth.uid()));
create policy module_update on public.conference_contacts for update to authenticated using(public.has_permission('events.write')) with check(public.has_permission('events.write'));
create policy module_delete on public.conference_contacts for delete to authenticated using(public.has_permission('events.delete'));
create trigger module_revision before update on public.conference_contacts for each row execute function public.sales_touch_revision();
create trigger module_audit after insert or update or delete on public.conference_contacts for each row execute function public.audit_business_change();
create trigger module_references before insert or update on public.conference_contacts for each row execute function public.department_reference_guard();
create table public.workspace_events(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 200),activities text not null default '' check(length(activities)<=5000),responsible_id uuid not null references public.employee_profiles(id) on delete restrict,event_date date not null,status text not null check(status in ('Planned','Confirmed','In Progress','Completed','Cancelled')),notes text not null default '' check(length(notes)<=5000),owner_id uuid not null references public.employee_profiles(id) on delete restrict,revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.workspace_events enable row level security;
revoke all on public.workspace_events from anon,authenticated;
grant select,delete on public.workspace_events to authenticated;
grant insert(name,activities,responsible_id,event_date,status,notes,owner_id),update(name,activities,responsible_id,event_date,status,notes) on public.workspace_events to authenticated;
create policy module_read on public.workspace_events for select to authenticated using(public.has_permission('events.read'));
create policy module_insert on public.workspace_events for insert to authenticated with check(public.has_permission('events.write') and owner_id=(select auth.uid()));
create policy module_update on public.workspace_events for update to authenticated using(public.has_permission('events.write')) with check(public.has_permission('events.write'));
create policy module_delete on public.workspace_events for delete to authenticated using(public.has_permission('events.delete'));
create trigger module_revision before update on public.workspace_events for each row execute function public.sales_touch_revision();
create trigger module_audit after insert or update or delete on public.workspace_events for each row execute function public.audit_business_change();
create trigger module_references before insert or update on public.workspace_events for each row execute function public.department_reference_guard();
create policy priority_read on public.activities for select to authenticated using(workspace_kind='priorities' and public.has_permission('priorities.read'));
create policy priority_insert on public.activities for insert to authenticated with check(workspace_kind='priorities' and department is null and public.has_permission('priorities.write') and owner_id=(select auth.uid()));
create policy priority_update on public.activities for update to authenticated using(workspace_kind='priorities' and public.has_permission('priorities.write')) with check(workspace_kind='priorities' and department is null and public.has_permission('priorities.write'));
create policy priority_delete on public.activities for delete to authenticated using(workspace_kind='priorities' and public.has_permission('priorities.delete'));
create trigger priority_revision before update on public.activities for each row when(old.workspace_kind='priorities') execute function public.sales_touch_revision();
create trigger priority_completed before insert or update on public.activities for each row when(new.workspace_kind='priorities') execute function public.operations_task_completion();
create trigger priority_references before insert or update on public.activities for each row when(new.workspace_kind='priorities') execute function public.department_reference_guard();
create function public.team_priority_audit() returns trigger language plpgsql security definer set search_path='' as $$begin
 if (tg_op='DELETE' and old.workspace_kind='priorities') or (tg_op<>'DELETE' and new.workspace_kind='priorities') then insert into public.audit_records(actor_id,entity,record_id,action) values(auth.uid(),'team_priorities',case when tg_op='DELETE' then old.id else new.id end,tg_op);end if;
 if tg_op='DELETE' then return old;else return new;end if;end $$;
revoke all on function public.team_priority_audit() from public;
create trigger priority_audit after insert or update or delete on public.activities for each row execute function public.team_priority_audit();
create index it_issues_project_idx on public.it_issues(project_id);
create index conference_followup_idx on public.conference_contacts(follow_up_date,status);
create function public.conference_reference_guard() returns trigger language plpgsql set search_path='' as $$
begin if new.contact_id is not null and not exists(select 1 from public.contacts where id=new.contact_id and account_id=new.account_id) then raise exception 'Contact must belong to the selected institution' using errcode='23514';end if;return new;end $$;
revoke all on function public.conference_reference_guard() from public;
create trigger conference_contact_guard before insert or update on public.conference_contacts for each row execute function public.conference_reference_guard();
create view public.team_priorities_list with(security_invoker=true) as select a.*,d.name as team_department_label,e.full_name as assigned_to_label,concat_ws(' ',a.title,d.name,e.full_name,a.priority,a.status,a.due_at) as search_text from public.activities a left join public.departments d on d.id=a.team_department left join public.employee_profiles e on e.id=a.assigned_to where a.workspace_kind='priorities';
create view public.it_projects_list with(security_invoker=true) as select p.*,e.full_name as responsible_id_label,v.total_tasks,v.completed_tasks,case when v.total_tasks=0 then 0 else round(100.0*v.completed_tasks/v.total_tasks)::integer end as progress,concat_ws(' ',p.name,p.platform,p.description,e.full_name,p.status) as search_text from public.it_projects p left join public.employee_profiles e on e.id=p.responsible_id left join lateral(select count(*)::integer total_tasks,count(*) filter(where status='Completed')::integer completed_tasks from public.it_issues where project_id=p.id) v on true;
create view public.it_issues_list with(security_invoker=true) as select i.*,e.full_name as assigned_to_label,p.name as project_id_label,concat_ws(' ',i.title,i.platform,i.issue_type,i.priority,i.status,e.full_name,p.name) as search_text from public.it_issues i left join public.employee_profiles e on e.id=i.assigned_to left join public.it_projects p on p.id=i.project_id;
create view public.conference_contacts_list with(security_invoker=true) as select c.*,a.name as account_id_label,e.full_name as responsible_id_label,concat_ws(' ',c.contact_person,c.email_phone,c.country,c.contact_type,c.status,c.topic,c.next_step,a.name,e.full_name) as search_text from public.conference_contacts c left join public.accounts a on a.id=c.account_id left join public.employee_profiles e on e.id=c.responsible_id;
create view public.workspace_events_list with(security_invoker=true) as select v.*,e.full_name as responsible_id_label,concat_ws(' ',v.name,v.activities,v.notes,v.status,e.full_name,v.event_date) as search_text from public.workspace_events v left join public.employee_profiles e on e.id=v.responsible_id;
grant select on public.team_priorities_list,public.it_projects_list,public.it_issues_list,public.conference_contacts_list,public.workspace_events_list to authenticated;
commit;
